    (bl : list word),
  (0 < SZ /\ SZ + 16384 <= 2^47)%Z -> (0 <= k < 64)%Z ->
  gobj P (sa_msz SZ) lo -> gobj PAB (8 * Z.of_nat (length ws)) lo ->
  (0 <= n < Z.of_nat (length ws))%Z ->
  rw_cells asegs m1 (bv_unsigned sp) [CB 8 j; C8 s9c; C8 s8c; C8 s7c; C8 s6c; C8 s5c; C8 s4c; C8 s3c; C8 s2c; C8 s1c; C8 s0c; C8 rac] ->
